  1	package it.unina.reservations.controller;
  2	
  3	import it.unina.reservations.controller.strategy.FirstAvailableAssignment;
  4	import it.unina.reservations.controller.strategy.AssignmentStrategy;
  5	import it.unina.reservations.dto.ReservationDTO;
  6	import it.unina.reservations.dto.ReservationRequestDTO;
  7	import it.unina.reservations.dto.StatisticsDTO;
  8	import it.unina.reservations.entity.*;
  9	import it.unina.reservations.entity.state.ActiveState;
 10	
 11	import java.time.LocalDate;
 12	import java.time.LocalDateTime;
 13	import java.time.LocalTime;
 14	import java.time.ZoneId;
 15	import java.util.*;
 16	
 17	/**
 18	  * English implementation note.
 19	 * MakeReservation (UC7), CancelReservation (UC9), PerformCheckIn (UC10),
 20	  * English implementation note.
 21	  * English implementation note.
 22	 * ({@code assignmentStrategy}).
 23	 */
 24	public class ReservationManager {
 25	
 26	    private static ReservationManager instance;
 27	
 28	    private final ReservationRegistry reservationRegistry = ReservationRegistry.getInstance();
 29	    private final StudyRoomRegistry roomRegistry = StudyRoomRegistry.getInstance();
 30	    private final UserRegistry userRegistry = UserRegistry.getInstance();
 31	    private AssignmentStrategy assignmentStrategy;
 32	
 33	
 34	    private ReservationManager() {}
 35	
 36	    public static ReservationManager getInstance() {
 37	        if (instance == null) {
 38	            instance = new ReservationManager();
 39	            instance.setAssignmentStrategy(new FirstAvailableAssignment());
 40	        }
 41	        return instance;
 42	    }
 43	
 44	
 45	    /** English implementation note. */
 46	    void setAssignmentStrategy(AssignmentStrategy assignmentStrategy){
 47	        this.assignmentStrategy = assignmentStrategy;
 48	    }
 49	
 50	    /** English implementation note. */
 51	    private Student resolveStudent(Long studentId){
 52	        Student student = userRegistry.findStudentById(studentId);
 53	        if(student == null){
 54	            throw new IllegalArgumentException("Student not found.");
 55	        }
 56	        return student;
 57	    }
 58	
 59	
 60	    // ------------------------------------------------------------------ UC7
 61	    /**
 62	      * English implementation note.
 63	      * English implementation note.
 64	     */
 65	    public ReservationDTO makeReservation(ReservationRequestDTO request) {
 66	        Long roomId = request.getRoomId();
 67	        Long areaId = request.getAreaId();
 68	        Long seatId = request.getSeatId();
 69	        LocalDate date = request.getDate();
 70	        Long timeSlotId = request.getTimeSlotId();
 71	        Long studentId = request.getStudentId();
 72	
 73	        // English implementation note.
 74	        Student student = resolveStudent(studentId);
 75	        StudyRoom room = resolveRoom(roomId, date);
 76	        Area area = resolveArea(room, areaId);
 77	        TimeSlot timeSlot = resolveTimeSlot(room, timeSlotId, date);
 78	
 79	        // English implementation note.
 80	        validateSeatInArea(area, seatId);
 81	
 82	        // English implementation note.
 83	        // English implementation note.
 84	        synchronized (this){
 85	            // English implementation note.
 86	            validateUniqueness(student, date, timeSlot);
 87	
 88	            // English implementation note.
 89	            List<Seat> available = availableSeats(area, date, timeSlot);
 90	
 91	            // English implementation note.
 92	            Seat seat = selectSeat(seatId, date, timeSlot, available);
 93	
 94	            // English implementation note.
 95	            Reservation reservation = createAndSave(student, date, timeSlot, seat);
 96	            // English implementation note.
 97	            //    e non si notify reservations mai saved.
 98	            notifyReservation(reservation);
 99	            return toDTO(reservation);
100	        }
101	
102	    }
103	
104	    private void validateSeatInArea(Area area, Long seatId) {
105	        if(seatId == null){
106	            throw new IllegalArgumentException("Seat not provided");
107	        }
108	        if(seatId != 0){
109	            Seat seat = roomRegistry.findSeatById(seatId);
110	            if(seat == null){
111	                throw new IllegalArgumentException("Invalid seat identifier.");
112	            }
113	            // English implementation note.
114	            if(!area.getId().equals(seat.getArea().getId())){
115	                throw new IllegalArgumentException("The seat is not in the selected area");
116	            }
117	        }
118	    }
119	
120	    private void notifyReservation(Reservation reservation) {
121	        reservation.attach(NotificationManager.getInstance());
122	        reservation.notifyObservers();
123	    }
124	
125	    private Reservation createAndSave(Student student, LocalDate date, TimeSlot timeSlot, Seat seat) {
126	
127	        Reservation reservation = new Reservation();
128	        reservation.setDate(date);
129	        reservation.setTimeSlot(timeSlot);
130	        reservation.setSeat(seat);
131	        reservation.setStudent(student); // English implementation note.
132	        reservation.setState(ActiveState.getInstance());
133	
134	        boolean success = reservationRegistry.saveReservation(reservation);
135	        if (!success){
136	            throw new RuntimeException("Server error: the reservation could not be saved. Please try again.");
137	        }
138	
139	        return reservation;
140	    }
141	
142	    private List<Seat> availableSeats(Area area, LocalDate date, TimeSlot timeSlot) {
143	        // English implementation note.
144	        List<Seat> available = area.getAvailableSeats(date, timeSlot);
145	        if(available.isEmpty()){
146	            throw new IllegalArgumentException("No seats are available in the selected area");
147	        }
148	        return available;
149	    }
150	
151	    private void validateUniqueness(Student student, LocalDate date, TimeSlot timeSlot) {
152	        if(student.hasActiveOrConfirmedReservationForDateAndSlot(date, timeSlot.getLabel())){
153	            throw new IllegalArgumentException("You already have an active or confirmed reservation for this date and time slot");
154	        }
155	    }
156	
157	    private Area resolveArea(StudyRoom room, Long areaId) {
158	        if (areaId == null) {
159	            throw new IllegalArgumentException("Area not specified");
160	        }
161	        if (areaId < 1){
162	            throw new IllegalArgumentException("Invalid area identifier.");
163	        }
164	
165	        Area area = roomRegistry.findAreaById(areaId);
166	        if(area == null || !area.getStudyRoom().getId().equals(room.getId())){
167	            throw new IllegalArgumentException("The area is not in the selected room");
168	        }
169	
170	        return area;
171	    }
172	
173	    private StudyRoom resolveRoom(Long roomId, LocalDate date) {
174	        if(roomId == null){
175	            throw new IllegalArgumentException("A study room must be selected");
176	        }
177	        if(roomId < 1){
178	            throw new IllegalArgumentException("Invalid room identifier");
